/* Postmarked Elsewhere, crisp vector art and cooperative browser client. */
(()=>{'use strict';
const E=window.PostmarkedEngine;const root=document.getElementById('app');if(!E){root.textContent='The sorting office failed to open. Please refresh.';return;}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={mail:'✉',fold:'⌁',rotate:'↻',time:'◷',stamp:'✦',chat:'◉',clue:'◎',dispatch:'➤',inspect:'⌕',moon:'☾',water:'≋',clock:'◷',done:'✓',alert:'!',note:'▤',atlas:'◇',lock:'⌑',players:'♧',link:'⛓'};
const savedName=(()=>{try{return localStorage.getItem('postmarked-name')||'Explorer'}catch{return'Explorer'}})();
const ui={screen:'home',name:savedName,difficulty:'standard',visibility:'private',joinCode:(new URLSearchParams(location.search).get('room')||'').toUpperCase(),online:false,game:null,playerId:null,token:null,stream:null,modal:null,draft:'',notice:null,lastSeq:null,publicRooms:[],busy:false,homeTab:'home',inspectedOpen:null,deskMode:'letter',letterSide:'front',sidePanel:null,pendingStart:null,introDismissedFor:null,lastDeliveryIndex:null};
function icon(n){return icons[n]||'✦'}
function fmtTime(t){return new Date(t).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}
function attr(v){return esc(v).replace(/`/g,'&#96;')}
function nameOf(g,id){return g?.players.find(p=>p.id===id)?.name||'An explorer'}
function cat(t){return ['DELIVERED','FINISH'].includes(t)?'success':['MISHAP','TIME'].includes(t)?'error':''}
function setNotice(text,type=''){ui.notice={text,type,serial:Date.now()};render();const serial=ui.notice.serial;setTimeout(()=>{if(ui.notice?.serial===serial){ui.notice=null;render()}},4200)}
// Crisp vector paper-theatre scene. Every interactive part is SVG, never a raster stretched to fit.
function sceneSVG(g,hero=false){
 const d=g?.deliveries?.[g?.index||0]||E.makeContracts(2)[0];
 const w=g?.world||{foldHolder:null,angle:0,dial:'DUSK',stamp:null};
 const conservatory=d.id==='conservatory',held=!!w.foldHolder,gateAligned=!!w.aligned,routeBridged=held&&gateAligned;
 const targetEast=conservatory||d.requiredAngle===3, destX=targetEast?767:266, sourceX=targetEast?160:865;
 const dusk=w.dial==='DUSK', midnight=w.dial==='MIDNIGHT', lowWater=w.dial==='LOW';
 const heading=E.DIRECTIONS[w.angle]||'NORTH',theta=w.angle*90;
 const sky0=midnight?'#15283b':dusk?'#564a5c':'#91a8a5',sky1=midnight?'#46556a':dusk?'#c79181':'#e6c9a2';
 const winLight=midnight?'#efc681':dusk?'#edbe83':'#efdda6';
 const stageView=`<defs>
  <linearGradient id="skyPostal" x2="0" y2="1"><stop stop-color="${sky0}"/><stop offset="1" stop-color="${sky1}"/></linearGradient>
  <linearGradient id="canalPostal" x2=".3" y2="1"><stop stop-color="#244553"/><stop offset=".55" stop-color="#47798a"/><stop offset="1" stop-color="#263b48"/></linearGradient>
  <linearGradient id="roofPostal" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#8c5e5c"/><stop offset="1" stop-color="#413941"/></linearGradient>
  <linearGradient id="paperPostal" x2="0" y2="1"><stop stop-color="#eadbc0"/><stop offset="1" stop-color="#cbb896"/></linearGradient>
  <linearGradient id="copperPostal"><stop stop-color="#d3aa78"/><stop offset=".6" stop-color="#a6785f"/><stop offset="1" stop-color="#75524d"/></linearGradient>
  <linearGradient id="glassPostal"><stop stop-color="#e9f1d4"/><stop offset=".6" stop-color="#86afb1"/><stop offset="1" stop-color="#315a64"/></linearGradient>
  <pattern id="grainPostal" width="23" height="19" patternUnits="userSpaceOnUse"><circle cx="2" cy="4" r=".8" fill="#563c37" opacity=".16"/><path d="M7 15l11-8" stroke="#664f47" stroke-width=".6" opacity=".11"/></pattern>
  <pattern id="cobblePostal" width="26" height="17" patternUnits="userSpaceOnUse"><path d="M0 0h26M0 16h26M13 0V8M0 8h13M13 8h13" stroke="#9e8d75" fill="none" stroke-width=".9" opacity=".55"/></pattern>
  <filter id="shadowPostal" x="-35%" y="-50%" width="175%" height="210%"><feDropShadow dx="0" dy="7" stdDeviation="4" flood-color="#20262a" flood-opacity=".27"/></filter>
 </defs>`;
 const building=(x,y,s=1,colors=0)=>{
  const wall=colors===0?'#b9a28c':colors===1?'#8f9f97':'#b6a39c';
  const wallSide=colors===0?'#827163':colors===1?'#5a7775':'#736764';
  return `<g transform="translate(${x} ${y}) scale(${s})" filter="url(#shadowPostal)">
   <path d="M-41 -97L19 -129L64 -110L3 -78Z" fill="url(#roofPostal)" stroke="#d2ad91" stroke-width="2"/>
   <path d="M3 -78L64 -110V-4L3 25Z" fill="${wallSide}" stroke="#6a5147" stroke-width="2"/>
   <path d="M-41 -97L3 -78V25L-41 5Z" fill="${wall}" stroke="#6a5147" stroke-width="2"/>
   <path d="M-34 -61l20 7v27l-20-7z" fill="${winLight}" stroke="#51443e" stroke-width="3"/>
   <path d="M13 -60l22-12v29l-22 12zM40 -74l13-7v29l-13 7z" fill="${winLight}" stroke="#51443e" stroke-width="3"/>
   <path d="M-36 -5l22 9M11 -9l40-20" stroke="#e1c5a0" stroke-width="3" opacity=".7"/>
   <path d="M-12 -39l11 5v43l-11-5z" fill="#313b40" stroke="#d8ba93" stroke-width="2"/>
   <path d="M-45 8L5 30L68-4" fill="none" stroke="#d5b996" stroke-width="5"/>
  </g>`;
 };
 const street=(left)=>{
  const x=left?65:562;
  return `<g>
   <path d="M${x} 370L${left?451:966} 360L${left?444:967} 529H${x+6}Z" fill="#c1ae91" stroke="#82715f" stroke-width="3"/>
   <path d="M${x+6} 387L${left?448:961} 381L${left?443:963} 526L${x+6} 526Z" fill="url(#cobblePostal)"/>
   <path d="M${x+15} 443H${left?454:970}" stroke="#eed6a9" stroke-width="4"/>
   <path d="M${x+8} 454H${left?455:968}" stroke="#5c5750" stroke-width="7" opacity=".6"/>
  </g>`;
 };
 const postalDeco=(x,y)=>`<g transform="translate(${x} ${y})"><path d="M0 0v-53" stroke="#483d39" stroke-width="4"/><path d="M-9-46l9-10 9 10-3 22h-12z" fill="${winLight}" stroke="#846c55" stroke-width="3"/><ellipse cy="-35" rx="19" ry="22" fill="#f0ca86" opacity=".16"/></g>`;
 const depot=(x)=>`<g transform="translate(${x} 333)" filter="url(#shadowPostal)"><rect x="-76" y="-132" width="152" height="156" fill="#6b7771" stroke="#d3baa0" stroke-width="4"/>
 <path d="M-89 -130L-20 -176L89 -130Z" fill="#55454a" stroke="#d4aa80" stroke-width="4"/>
 <path d="M-64 -88h33v34h-33zM9 -88h32v34H9z" fill="${winLight}" stroke="#473f3b" stroke-width="4"/>
 <path d="M-19 25v-60q19-24 39 0v60" fill="#2b3d3d" stroke="#ddbd91" stroke-width="5"/>
 <rect x="-84" y="-127" width="169" height="25" fill="#263a3f" stroke="#cfac7e" stroke-width="2"/>
 <text x="0" y="-109" text-anchor="middle" fill="#f5dcaa" font-size="13" font-weight="750" letter-spacing="1">NIGHT POST</text>
 <path d="M-90 28H91" stroke="#e2c9a2" stroke-width="9"/>
 </g>`;
 const destination=(x)=>`<g transform="translate(${x} 353)" filter="url(#shadowPostal)">
 ${conservatory?`<path d="M-86 -31V-133L0 -205L86 -133V-31Z" fill="url(#glassPostal)" stroke="#d1b791" stroke-width="7"/>
 <path d="M-85 -134H86M-65 -83H65M0 -204V-30" fill="none" stroke="#dfd3bd" stroke-width="5"/>
 <path d="M-67 -146L0 -200L66 -146" fill="none" stroke="#5c7070" stroke-width="7"/>`:
 `<path d="M-83 -35V-183H83V-35Z" fill="#b29c88" stroke="#cdb18f" stroke-width="5"/>
 <path d="M-100 -181L-1 -246L99 -181Z" fill="url(#roofPostal)" stroke="#dab28b" stroke-width="5"/>
 <path d="M-65 -153h28v30h-28zM34 -153h28v30H34z" fill="${winLight}" stroke="#5a4b45" stroke-width="4"/>
 <circle cx="0" cy="-177" r="28" fill="#ead8ae" stroke="#4e4c46" stroke-width="6"/>
 <path d="M0 -177v-15m0 15l13 8" stroke="#5a514d" stroke-width="4" stroke-linecap="round"/>`}
 <path d="M-37 -34v-58q37-34 74 0v58" fill="#26363b" stroke="#d6bb93" stroke-width="7"/>
 <path d="M-87 -28H90" stroke="#eee0c5" stroke-width="11"/>
 <g transform="translate(0 -1)"><rect x="-67" width="134" height="29" rx="3" fill="#e8d3ab" stroke="#5e4f47" stroke-width="3"/>
 <text x="0" y="20" text-anchor="middle" font-size="15" fill="#463735" font-weight="900">${esc(conservatory?'GLASSHOUSE':d.recipient.toUpperCase())}</text></g>
 <g transform="translate(0 -103)"><circle r="34" fill="#233c42" stroke="#e0bc87" stroke-width="5"/>
 ${Array.from({length:8},(_,i)=>`<path d="M0 -25v5" transform="rotate(${i*45})" stroke="#a7bcb0" stroke-width="2"/>`).join('')}
 <g class="v4-gate-hand" style="transform-origin:center" transform="rotate(${theta})"><path d="M-6 -25H6L8 -5L0 20L-8 -5Z" fill="${gateAligned?'#c9f0d6':'#ffd68c'}" stroke="#354740" stroke-width="2"/></g>
 <circle r="5" fill="#f9eac8"/></g>
 </g>`;
 const waterTop=lowWater?266:218;
 const canal=`<path d="M457 ${waterTop}Q495 263 485 341T486 565H578Q543 479 565 365T576 ${waterTop}Z" fill="url(#canalPostal)" stroke="#9ab3b1" stroke-width="4"/>
  ${Array.from({length:16},(_,i)=>{let x=516+Math.sin(i*.62)*13,y=waterTop+23+i*19;return `<path d="M${x-22} ${y}q22-8 44 0" fill="none" stroke="#c2ddd6" stroke-width="${i%3===0?2.8:1}" opacity="${i%3===0?.62:.27}"/>`}).join('')}`;
 const bridge=!held?`<g class="paper-bridge folded"><path d="M${targetEast?448:581} 434l${targetEast?-54:54} -60 21 -16 35 63Z" fill="#c29a6c" stroke="#f8e0ae" stroke-width="5"/>
 <path d="M${targetEast?453:581} 426l${targetEast?-41:41} -43" stroke="#71543f" stroke-width="3"/></g>`:
 `<g class="paper-bridge expanded" filter="url(#shadowPostal)"><path d="M441 425L593 425L603 460H432Z" fill="url(#copperPostal)" stroke="#ffe1ac" stroke-width="5"/>
 ${Array.from({length:8},(_,i)=>`<path d="M${447+i*19} 428l-3 29" stroke="#72573f" stroke-width="3"/>`).join('')}
 <path d="M438 418H594M433 465H600" stroke="#eacb96" stroke-width="5"/></g>`;
 const originTo=targetEast?344:688;
 const line1=targetEast?`M165 394H432`:`M860 394H604`;
 const line2=targetEast?`M604 394H758`:`M432 394H274`;
 const route=`<g class="route-markings"><path d="${line1}" fill="none" stroke="#f5dbae" stroke-width="7" opacity=".9" stroke-dasharray="11 14"/>
 ${held?`<path d="M444 442H593" fill="none" stroke="${gateAligned?'#bdebd0':'#f5d49d'}" stroke-width="7" stroke-dasharray="10 12"/>`:''}
 ${held&&gateAligned?`<path d="${line2}" fill="none" stroke="#bdebd0" stroke-width="7" opacity=".9" stroke-dasharray="11 14"/>`:''}</g>`;
 const hills=`<path d="M47 323Q146 256 274 301T490 303Q561 251 653 299T977 282V384H47Z" fill="#374a4a" opacity=".45"/><path d="M47 375Q171 334 303 374T659 364T978 343V425H47Z" fill="#715c57" opacity=".26"/>`;
 const background=`<rect x="23" y="22" width="978" height="576" rx="7" fill="#213038" stroke="#8b6e53" stroke-width="4"/>
 <rect x="35" y="35" width="954" height="552" fill="url(#paperPostal)" stroke="#c0a37d" stroke-width="3"/>
 <rect x="43" y="45" width="937" height="532" fill="url(#grainPostal)"/>
 <rect x="49" y="114" width="927" height="327" fill="url(#skyPostal)"/>
 ${Array.from({length:11},(_,i)=>`<path d="M${70+i*86} 124v308" stroke="#d8c09b" stroke-width="1" opacity=".08"/>`).join('')}
 ${hills}${street(true)}${street(false)}${canal}`;
 const labels=`<rect x="50" y="49" width="925" height="62" fill="#1d3139" opacity=".98"/>
 <text x="74" y="78" fill="#f0e1c6" font-size="23" font-family="Georgia,serif" letter-spacing="1.6">${conservatory?'CAIRN RIDGE · FOLDING SURVEY':'BLACKWATER LANE · NIGHT ATLAS'}</text>
 <text x="74" y="97" fill="#a9cac1" font-size="11" letter-spacing="3" font-family="sans-serif">FILE ${esc(d.number)}    /    THE STREET ISN’T FINISHED</text>
 <g transform="translate(915 77)" fill="#f3d9ac"><path d="M0 14V-15L-6-4L0-17L6-4Z" stroke="#e5c192"/><text y="-22" text-anchor="middle" font-size="12" font-weight="900">N</text><text y="29" text-anchor="middle" font-size="9">S</text><text x="-25" y="3" text-anchor="middle" font-size="9">W</text><text x="25" y="3" text-anchor="middle" font-size="9">E</text></g>
 <text x="98" y="163" fill="#f0ddbd" font-size="12" font-weight="800" letter-spacing="1.4">WEST QUAY</text>
 <text x="802" y="163" fill="#f0ddbd" font-size="12" font-weight="800" letter-spacing="1.4">EAST QUAY</text>
 <g transform="translate(${sourceX} 186)"><rect x="-89" y="-19" width="178" height="34" rx="3" fill="#23474c" stroke="#e3bb87" stroke-width="2"/><text x="0" y="3" text-anchor="middle" fill="#f3dec0" font-size="14" font-weight="800">START · POST OFFICE</text></g>
 <g transform="translate(${destX} 191)"><rect x="-99" y="-19" width="198" height="34" rx="3" fill="#664d43" stroke="#f0cc91" stroke-width="2"/><text x="0" y="3" text-anchor="middle" fill="#fff0d5" font-size="14" font-weight="800">DESTINATION · ${esc(conservatory?'GLASSHOUSE':d.recipient.toUpperCase())}</text></g>
 <rect x="51" y="546" width="923" height="35" fill="#efe0c3" opacity=".95"/>
 <text x="70" y="568" font-family="Georgia,serif" font-size="16" fill="#65493d">${esc(d.region)} · ${esc(d.recipient)}</text>
 <text x="953" y="565" text-anchor="end" font-size="11" font-weight="900" fill="#785949">BRIDGE ${held?'EXTENDED':'FOLDED'}   ·   GATE ${esc(heading)}</text>`;
 const topoDeco=`${building(targetEast?327:692,338,.68,0)}${building(targetEast?380:623,375,.55,1)}${building(targetEast?649:368,335,.62,2)}${building(targetEast?691:312,390,.48,1)}${postalDeco(88,431)}${postalDeco(922,432)}`;
 const moon=midnight?`<circle cx="909" cy="219" r="25" fill="#dbe4df" opacity=".76"/><circle cx="919" cy="211" r="23" fill="${sky0}"/>`:dusk?`<circle cx="906" cy="289" r="27" fill="#f3bb86" opacity=".62"/>`:`<circle cx="901" cy="210" r="21" fill="#f5d9a6"/>`;
 const hotspots=hero?'':`<g class="world-hotspot" role="button" tabindex="0" data-act="fold" aria-label="${held?'Release the bridge':'Extend the hinged bridge'}" transform="translate(${targetEast?421:607} 512)"><circle r="24" fill="#1e4549" stroke="#f2cb94" stroke-width="3"/><path d="M-13 0H13M5 -8l9 8-9 8" stroke="#fff3cf" fill="none" stroke-width="3"/><rect x="-56" y="28" width="112" height="23" rx="3" fill="#1c3439" stroke="#dfb982"/><text text-anchor="middle" y="45" font-size="12" fill="#f1dab2" font-weight="800">${held?'RELEASE BRIDGE':'EXTEND BRIDGE'}</text></g>
 <g class="world-hotspot" role="button" tabindex="0" data-act="rotate" data-dir="1" aria-label="Rotate the clocktower entrance" transform="translate(${destX+92} 391)"><circle r="24" fill="#1e4549" stroke="#f2cb94" stroke-width="3"/><text text-anchor="middle" y="10" font-size="31" fill="#fff3cf">↻</text><rect x="-54" y="28" width="108" height="23" rx="3" fill="#1c3439" stroke="#dfb982"/><text text-anchor="middle" y="45" font-size="12" fill="#f1dab2" font-weight="800">TURN ENTRANCE</text></g>`;
 const routeLabel=routeBridged?'ROUTE CONNECTED':held?'BRIDGE EXTENDED · ENTRANCE MISALIGNED':'BRIDGE FOLDED · CROSSING BLOCKED';
 return `<svg class="world-svg v4-world" viewBox="0 0 1024 620" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Illustrated postal world. Postal depot on ${targetEast?'west':'east'} bank; delivery target on ${targetEast?'east':'west'} bank. A canal blocks the street, and a hinged bridge and rotating gate can reconnect it.">
 ${stageView}${background}${moon}${topoDeco}${depot(sourceX)}${destination(destX)}${route}${bridge}${g?.pendingDelivery?`<g class="v4-courier"><path d="M-12-7h24v16h-24z" fill="#ffe6b6" stroke="#734e3a" stroke-width="3"/><path d="M-12-7L0 2L12-7" stroke="#8f6247" stroke-width="2" fill="none"/><animateMotion path="${targetEast?`M${sourceX} 398L438 438L592 438L${destX} 398`:`M${sourceX} 398L592 438L438 438L${destX} 398`}" dur="1.8s" fill="freeze" repeatCount="1"/></g>`:''}${labels}
 <rect x="73" y="474" width="${routeBridged?240:held?310:270}" height="30" rx="3" fill="${routeBridged?'#315c50':'#694d42'}" stroke="#e3be86" stroke-width="2"/>
 <text x="88" y="495" font-size="13" font-weight="800" fill="#fae7c5">${routeLabel}</text>
 ${hotspots}
 </svg>`;
}
function logo(){return `<button class="brand" data-act="home"><span class="brand-seal">✉</span><span><span class="brand-name">POSTMARKED<br>ELSEWHERE</span><span class="brand-sub">DELIVERIES TO IMPOSSIBLE PLACES</span></span></button>`}
function shell(content){return `<header class="site-head">${logo()}<div class="head-right"><span class="build-mark"><span class="status-dot"></span> PLAYTEST 0.4</span>${ui.screen!=='home'?`<button class="ghost-link" data-act="home">← Main desk</button>`:`<span class="eyebrow" style="font-size:10px">THE NIGHT SHIFT</span>`}</div></header>${content}${ui.notice?`<div class="notice ${attr(ui.notice.type)}" role="status">${esc(ui.notice.text)}</div>`:''}${ui.modal?dialog():''}`}
function home(){let show=E.createGame({solo:true,seed:17});return shell(`<section class="v2-home" aria-label="Postmarked Elsewhere opening screen">
 <div class="v2-home-story"><div class="v2-kicker">THE MINISTRY OF UNDELIVERABLE CORRESPONDENCE  /  1891</div><h1>Deliver to the<br><em>impossible.</em></h1><p class="v2-home-lead">An impossible address is not a mistake. It is an unfinished route.</p><p class="v2-home-sub">Read between the postmarks. Manipulate miniature worlds. Make their impossible destinations reachable before the night shift ends.</p><div class="v2-home-buttons"><button class="primary" data-act="solo">Begin solo shift <span aria-hidden="true">→</span></button><button class="secondary" data-act="coop">Play with friends <span class="v2-btn-detail">2–4 players</span></button></div><button class="v2-link" data-act="how">What kind of game is this? <span aria-hidden="true">↗</span></button><div class="v2-home-foot">AN ADULT COOPERATIVE MYSTERY <span>·</span> NO DOWNLOAD REQUIRED</div></div>
 <div class="v2-home-picture" aria-hidden="true"><div class="v2-home-atlas">${sceneSVG(show,true)}</div><div class="v2-home-envelope"><div class="v2-envelope-top"><span>THE NIGHT POST</span><span>017 / UNDELIVERABLE</span></div><span class="v2-envelope-label">RECIPIENT UNKNOWN</span><strong>Blackwater Lane,<br>East Quay</strong><p>A divided street. A hinged bridge.<br>One doorway that turns.</p><span class="v2-envelope-seal">✳</span></div><div class="v2-home-caption">An address is evidence. The map is a machine.</div></div>
 </section>`)}
function briefing(){let online=!!ui.game?.code&&!ui.game?.solo;return shell(`<section class="v2-intro"><div class="v2-intro-paper"><div class="v2-intro-stamp">MINISTRY ARCHIVE / 001</div><div class="v2-intro-eyebrow">A NIGHT AT THE MINISTRY</div><h1>Two letters. <em>One broken city.</em></h1><p class="v2-intro-lede">Welcome to the Ministry. Our correspondents are real. Their destinations are not always so cooperative.</p><div class="v2-intro-steps"><div><b>01</b><span><strong>Examine the letter</strong><small>Locate the named quay and its delivery condition.</small></span></div><div><b>02</b><span><strong>Open its little world</strong><small>See why the courier cannot reach the door; fix the crossing with the hinge and directional gate.</small></span></div><div><b>03</b><span><strong>Make the delivery</strong><small>Read the register to choose the correct hour and seal, then send.</small></span></div></div><div class="v2-intro-footer">${online?`<p>Your teammates are on the same shift. You can work independently or use the chat to coordinate.</p>`:`<label for="intro-difficulty">Choose your pace</label><select class="field" id="intro-difficulty" data-field="difficulty"><option value="relaxed" ${ui.difficulty==='relaxed'?'selected':''}>Untimed · learn the mechanics</option><option value="standard" ${ui.difficulty==='standard'?'selected':''}>Standard · 15 minutes</option><option value="expert" ${ui.difficulty==='expert'?'selected':''}>Expert · 8 minutes</option></select>`}<button class="primary" data-act="intro-enter">Open the first letter →</button></div></div><div class="v2-intro-side"><div class="v2-intro-quote">“The address is correct. <em>Reality is not.</em>”</div><div class="v2-intro-art" aria-hidden="true"><div class="v2-intro-stamp-art">✉</div><div class="v2-intro-routing">RETURN TO A PLACE THAT EXISTS</div></div></div></section>`)}
function auth(){const matched=ui.publicRooms.map(r=>`<div class="room-entry"><div><p>${esc(r.host)}'s night shift</p><small>${r.count} / 4 · ${esc(r.difficulty)}</small></div><button class="subtle" data-act="join-public" data-code="${attr(r.code)}">Join ${esc(r.code)}</button></div>`).join('');return shell(`<div class="auth-layout"><div class="auth-hero"><span class="eyebrow">THE GUEST REGISTER</span><h1>Who is on<br><i>the night shift?</i></h1><p>Invite two to four players into the same sorting office. Everyone manipulates the same folded world in real time. You won't see player avatars; you'll see their cursors of influence, decisions and deliveries.</p><p style="margin-top:19px;font-family:Georgia,serif;font-size:18px">Prefer working alone? <button class="subtle" data-act="solo">Start a solo shift →</button></p></div><div class="auth-card"><h2>Enter the register</h2><label class="label" for="yourname">Name in the ledger</label><input class="field" id="yourname" data-field="name" maxlength="22" value="${attr(ui.name)}" placeholder="Explorer"><label class="label" for="difficulty">Shift difficulty</label><select class="field" id="difficulty" data-field="difficulty"><option value="standard" ${ui.difficulty==='standard'?'selected':''}>Standard · 15-minute shift</option><option value="expert" ${ui.difficulty==='expert'?'selected':''}>Expert · 8-minute shift</option><option value="relaxed" ${ui.difficulty==='relaxed'?'selected':''}>Untimed · full puzzle, no clock</option></select><div class="label">How should others enter?</div><div class="auth-controls"><button class="${ui.visibility==='private'?'primary':'secondary'}" data-act="set-vis" data-value="private">Private room</button><button class="${ui.visibility==='public'?'primary':'secondary'}" data-act="set-vis" data-value="public">Public room</button></div><button class="primary" data-act="create" ${ui.busy?'disabled':''}>Create night shift →</button><div class="line" style="margin:22px 0"></div><h2>Join an existing shift</h2><label class="label" for="code">Six-character room code</label><div class="auth-row"><input class="field" id="code" data-field="joinCode" value="${attr(ui.joinCode)}" placeholder="E.G. Q9N5L2" style="max-width:170px;text-transform:uppercase;flex:1"><button class="secondary" data-act="join">Join by code</button></div><div class="label" style="margin-top:24px">Open public offices <button class="subtle" data-act="refresh-public" style="float:right;font-size:11px;padding:3px 8px">Refresh</button></div><div class="room-list">${ui.publicRooms.length?matched:`<p style="font-size:12px">No public shifts waiting right now. Create one, or join a private code.</p>`}</div></div></div>`)}
function lobby(){const g=ui.game;if(!g)return home();let isHost=g.hostId===ui.playerId,me=g.players.find(x=>x.id===ui.playerId);const rows=g.players.map(p=>`<div class="player-row"><span>${p.id===g.hostId?'♛ ':''}${esc(p.name)} ${p.id===ui.playerId?'<small> · you</small>':''}</span><small>${p.ready?'✓ Ready':'Waiting…'} ${p.connected?'●':''}</small></div>`).join('');return shell(`<div class="auth-layout"><div class="auth-hero"><span class="eyebrow">REGISTRY ${esc(g.code)}</span><h1>The desk<br>is <i>open.</i></h1><p>Give your friends the six-character code or invitation link. Each human player joins separately; no bots are added to your shift.</p><div class="auth-row" style="margin-top:22px"><button class="primary" data-act="copy-link">Copy invitation link</button><button class="secondary" data-act="copy-code">Copy code</button></div><p style="margin-top:19px">Public rooms appear in the directory until the host starts. Private rooms require the link or code.</p></div><div class="auth-card"><span class="eyebrow">OFFICIAL GUEST REGISTER</span><div class="lobby-code">${esc(g.code)}</div><p>${g.players.length} / 4 real players · ${esc(g.visibility)} · ${esc(g.difficulty)}</p><div class="line" style="margin:18px 0"></div>${rows}<div class="line" style="margin:15px 0"></div><div class="auth-row"><button class="${me?.ready?'secondary':'primary'}" data-act="ready">${me?.ready?'✓ Ready · unready':'Mark ready'}</button>${isHost?`<button class="${g.players.length>=2&&g.players.every(p=>p.ready)?'primary':'secondary'}" data-act="start" ${g.players.length<2||g.players.some(p=>!p.ready)?'disabled':''}>Begin shift →</button>`:''}</div>${isHost?`<div style="margin-top:18px"><span class="label">Lobby visibility</span><button class="subtle" data-act="lobby-vis" data-value="${g.visibility==='private'?'public':'private'}">Switch to ${g.visibility==='private'?'public':'private'}</button></div>`:''}<p style="margin-top:20px">Host begins after at least two people join and everyone is ready. Your mail, chat and world will update live for all of you.</p></div></div>`)}
function shipment(g,d,i){let active=i===g.index,complete=i<g.index;return `<div class="shipment ${active?'active':''} ${complete?'complete':''}"><span class="stamp-number">${esc(d.number)}</span><div style="flex:1"><strong>${esc(d.name)}</strong><small>${complete?'✓ DELIVERED':active?'◉ ON THE SORTING DESK':'SEALED · NEXT ARRIVAL'}</small></div><span>${complete?'✓':active?'⌁':'⟡'}</span></div>`;}
function eventName(e){return e.type==='DELIVERED'?'✓':e.type==='FOLD'?'⌁':e.type==='ROTATE'?'↻':e.type==='DIAL'?'◷':e.type==='CHAT'?'☏':e.type==='MISHAP'?'!':e.type==='STAMP'?'✦':'✉'}
function play(){const g=ui.game;if(!g)return home();if(g.phase==='finished')return finish();if(g.phase==='lobby')return lobby();if(ui.lastDeliveryIndex!==g.index){ui.lastDeliveryIndex=g.index;ui.deskMode='letter';ui.letterSide='front';}
const d=E.current(g),w=g.world, status=E.solveStatus(g);let isMeHolder=w.foldHolder===ui.playerId,holder=g.players.find(p=>p.id===w.foldHolder);const dirLabel=E.DIRECTIONS[w.angle];let lim=E.limitSeconds(g),timed=lim!==null,sec=Math.max(0,Math.floor((Date.now()-g.startedAt)/1000)),remaining=timed?Math.max(0,lim-sec):null,timeText=timed?`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`:'UNTIMED';let eventRows=g.events.slice(-8).reverse().map(e=>`<div class="v2-event-row"><span class="v2-event-symbol">${eventName(e)}</span><div>${esc(e.message)}<small>${fmtTime(e.at)}</small></div></div>`).join('');let chatRows=g.chat.slice(-20).map(m=>`<div class="chat-bubble ${m.by===ui.playerId?'self':''}"><small>${esc(m.name)} · ${fmtTime(m.at)}</small>${esc(m.text)}</div>`).join('');
let lead=ui.deskMode==='letter'?(!w.inspected.includes('front')?['01 / THE ADDRESS','Open the letter: who is waiting, where, and under what condition?']:!w.inspected.includes('reverse')?['02 / THE OBSTACLE','Flip the envelope. The postal clerk left a note about why the route is broken.']:['03 / THE WORLD INSIDE','Locate the named building on the atlas. You know the destination, but you still need a route.']):ui.deskMode==='atlas'?(!w.foldHolder?['THE ROAD IS BLOCKED',d.id==='conservatory'?'The ridge covers the conservatory approach. Fold it back so the path can be held open.':'The hinged promenade hangs into the canal. Brace it across the gap.']:!status.routeAligned?['THE BRIDGE HAS REACHED THE OTHER BANK',d.id==='conservatory'?`The glasshouse gate faces ${esc(dirLabel.toLowerCase())}. The envelope names its required compass heading.`:`The gate currently faces ${esc(dirLabel.toLowerCase())}. Look at which side the courier approaches from and turn the entrance toward that side.`]:['THE ROAD IS NOW CONTINUOUS','The courier can cross. The address still gives the arrival condition; the register specifies postage.']):['FINAL DISPATCH',status.route?'Your route is physically connected. Verify the delivery conditions and postage.':'There is still no continuous path through the miniature city. Return to the atlas.'];
let letterBody=ui.letterSide==='reverse'?d.reverse:ui.letterSide==='ledger'?d.ledger:ui.letterSide==='atlas'?d.atlas:d.front;
let letterStage=`<div class="v2-paper-area"><div class="v2-document ${ui.letterSide==='reverse'?'reverse':''}"><div class="v2-document-header"><span>POSTMARKED ELSEWHERE</span><span>${esc(d.number)} · ${esc(d.region)}</span></div><div class="v2-paper-inner"><div class="v2-address-label">${ui.letterSide==='front'?'TO THE RECIPIENT':ui.letterSide==='reverse'?'REVERSE · POSTMARK':ui.letterSide==='ledger'?'POSTAL REGISTER':'CARTOGRAPHIC NOTES'}</div><h2>${ui.letterSide==='front'?esc(d.recipient):ui.letterSide==='reverse'?'The reverse of the letter':ui.letterSide==='ledger'?'The night-mail register':'Notes on the route'}</h2>${ui.letterSide==='front'&&w.inspected.includes('front')?`<div class="v3-addressline">${esc(d.addressLine||d.region)}</div><div class="v3-document-divider"></div><div class="v3-letter-legend">DELIVERY CONDITIONS</div><p>${esc(d.specialInstruction||d.front)}</p>`:`<p>${ui.letterSide==='front'?'The envelope is sealed. Open it to read the address and delivery instructions.':esc(letterBody)}</p>`}<div class="v2-paper-seal">${ui.letterSide==='front'?'✉':'✦'}</div></div><div class="v2-document-footer"><span>THE MINISTRY · NIGHT SORTING</span><span>UNDELIVERABLE</span></div></div><div class="v2-paper-actions"><button class="${ui.letterSide==='front'?'primary':'secondary'}" data-act="open-front">${w.inspected.includes('front')?'Read address again':'Open the letter'}</button><button class="${ui.letterSide==='reverse'?'primary':'secondary'}" data-act="open-back">Flip envelope ↻</button><button class="subtle" data-act="open-ledger">Postal register</button></div></div>`;
let foldControls=`<div class="v4-tool-stack">
 <div class="v4-machine-card"><div class="v4-machine-top"><span class="v4-machine-num">01 / CROSSING</span><span class="v4-machine-state ${w.foldHolder?'ready':''}">${w.foldHolder?'EXTENDED':'FOLDED'}</span></div>
 <h3>${d.id==='conservatory'?'The hinged ridge':'The hinged footbridge'}</h3>
 <p>${d.id==='conservatory'?'The ridge can lie flat across the flood channel.':'The bridge is folded beside the canal. It needs to reach the other quay.'}</p>
 <button class="${isMeHolder?'primary':'secondary'} v4-main-action" data-act="fold" ${w.foldHolder&&!isMeHolder?'disabled':''}>${isMeHolder?'Release the crossing':w.foldHolder?`${esc(holder?.name||'Teammate')} holds it`:'Extend and hold bridge →'}</button>
 ${!g.solo?'<small>In co-op, one worker must hold the bridge while another operates the gate.</small>':'<small>The desk clamp holds the bridge in solo mode.</small>'}</div>
 <div class="v4-machine-card"><div class="v4-machine-top"><span class="v4-machine-num">02 / ENTRANCE</span><span class="v4-machine-state ${status.routeAligned?'ready':''}">FACES ${esc(dirLabel)}</span></div>
 <h3>Rotate the doorway</h3>
 <p>${d.id==='conservatory'?'The envelope specifies which compass direction unlocks the glasshouse entrance.':'The brass arrow is the moving entrance. Point it toward the end of the bridge where the courier arrives.'}</p>
 <div class="v4-orientation"><span>W</span><div class="v4-compass-dial"><span style="transform:translate(-50%,-50%) rotate(${w.angle*90}deg)">↑</span></div><span>E</span></div>
 <div class="v4-control-pair"><button data-act="rotate" data-dir="-1" ${!w.foldHolder||(!g.solo&&isMeHolder)?'disabled':''} aria-label="Turn gate left">↶ Left</button><button data-act="rotate" data-dir="1" ${!w.foldHolder||(!g.solo&&isMeHolder)?'disabled':''} aria-label="Turn gate right">Right ↷</button></div>
 ${!w.foldHolder?'<small>First extend the crossing to engage the clocktower gearing.</small>':status.routeAligned?'<small>The gate now faces the courier’s approach.</small>':'<small>Use the north arrow on the atlas to reason about the direction.</small>'}
 </div>
 <div class="v4-machine-footer"><button data-act="open-back">Read transfer note ↗</button><button data-act="view-dispatch" class="v4-next-action">Next: set arrival conditions →</button></div>
 </div>`;
let dispatchControls=`<div class="v4-tool-stack">
 <div class="v4-machine-card"><div class="v4-machine-top"><span class="v4-machine-num">03 / DELIVERY TIME</span><span class="v4-machine-state">${esc(w.dial)}</span></div><h3>${esc(d.dialLabel)} conditions</h3><p>Use the letter’s delivery instructions. This setting affects when the courier may arrive.</p>
 <div class="v4-dial-row">${d.dialOptions.map(v=>`<button data-act="dial" data-value="${attr(v)}" class="${w.dial===v?'selected':''}">${esc(v)}</button>`).join('')}</div></div>
 <div class="v4-machine-card"><div class="v4-machine-top"><span class="v4-machine-num">04 / POSTAGE</span><span class="v4-machine-state ${w.stamp?'ready':''}">${esc(w.stamp||'NOT STAMPED')}</span></div><h3>Select the seal</h3><p>The postal register classifies the correct type of delivery.</p><div class="v4-dial-row">${E.STAMPS.map(v=>`<button data-act="stamp" data-value="${attr(v)}" class="${w.stamp===v?'selected':''}">${v==='NOCTURNE'?'☾ ':v==='EXPRESS'?'➤ ':'♧ '}${esc(v)}</button>`).join('')}</div><button class="v4-evidence-link" data-act="open-ledger">Read postal register ↗</button></div>
 ${g.incident&&!g.incident.cleared?`<div class="v4-machine-card v4-incident"><h3>Ink on the press</h3><p>Clean the three stains before stamping the next parcel.</p><div class="ink-stains">${g.incident.stains.map((on,i)=>`<button class="ink-spot ${on?'dirty':'clean'}" data-act="blot" data-spot="${i}" ${!on?'disabled':''} aria-label="Blot stain ${i+1}">${on?'✦':'✓'}</button>`).join('')}</div></div>`:''}
 <div class="v4-machine-footer v4-dispatch-bottom"><button data-act="view-atlas">← Return to route</button><button class="v4-next-action" data-act="dispatch" ${g.pendingDelivery?'disabled':''}>${g.pendingDelivery?'Courier crossing…':'Dispatch letter →'}</button><small>${status.route?'Route connected':'Route not yet complete'} · ${w.inspected.length}/4 evidence types examined</small></div></div>`;
let worldStage=`<div class="v4-atlas-layout">
 <div class="v4-world-main"><div class="v4-world-header"><div><span>THE MINISTRY ATLAS / ${esc(d.number)}</span><strong>${esc(d.region)} · ${esc(d.recipient)}</strong></div><small>Route repair / ${g.solo?'Solo':'Shared team world'}</small></div>
 <div class="v4-world-art">${sceneSVG(g)}</div>
 <div class="v4-route-caption"><span class="v4-route-icon ${w.foldHolder&&status.routeAligned?'ok':''}">${w.foldHolder&&status.routeAligned?'✓':'↗'}</span><strong>${w.foldHolder&&status.routeAligned?'A crossing reaches the door':w.foldHolder?'The crossing reaches the quay; the doorway still points elsewhere':'The canal interrupts the courier’s route'}</strong></div>
 <div class="v4-evidence-strip"><button data-act="open-front">Read address</button><button data-act="open-back">Read back of envelope</button><button data-act="open-ledger">Postal register</button></div>
 </div><aside class="v4-machine-dock"><div class="v4-dock-head"><span class="v4-dock-overline">${ui.deskMode==='atlas'?'OPERATE THE PAPER WORLD':'COMPLETE THE DISPATCH'}</span><h2>${ui.deskMode==='atlas'?'Repair the broken route':'Prepare the delivery'}</h2></div>${ui.deskMode==='atlas'?foldControls:dispatchControls}</aside></div>`;
let sideHtml=ui.sidePanel==='chat'?`<div class="v2-side-content"><h3>Team chat</h3><div class="v2-chat-stream" id="chatlist">${chatRows||'<p class="v2-muted">No messages yet. Share a discovery with a friend.</p>'}</div><form class="chat-form" data-form="chat"><input id="chatinput" placeholder="Message the team…" maxlength="280" value="${attr(ui.draft)}" ${g.solo?'disabled':''}><button type="submit" ${g.solo?'disabled':''}>➤</button></form>${g.solo?'<p class="v2-muted">Chat becomes available in public or private multiplayer.</p>':''}</div>`:ui.sidePanel==='events'?`<div class="v2-side-content"><h3>Recent activity</h3><div class="v2-events">${eventRows||'<p class="v2-muted">The office is quiet.</p>'}</div></div>`:ui.sidePanel==='postbag'?`<div class="v2-side-content"><h3>Tonight’s postbag</h3>${g.deliveries.map((mail,i)=>`<div class="v2-postbag-row"><b>${esc(mail.number)}</b><div><strong>${esc(mail.name)}</strong><small>${i<g.index?'✓ Delivered':i===g.index?'On your desk':'Still sealed'}</small></div></div>`).join('')}<p class="v2-muted">Two deliveries. Each requires evidence, not a guessed setting.</p></div>`:`<div class="v2-side-closed"><div class="v2-small-seal">✉</div><p><strong>${g.solo?'One desk. Two deliveries.':'The desk is shared.'}</strong></p><p>${g.solo?'Read the mail, then unfold its destination.':'Use chat and real-time changes to solve the shift together.'}</p><div class="v2-next-detail">LAST ACTION<br><span>${esc(g.events.at(-1)?.message||'The office is waiting.')}</span></div></div>`;
return shell(`<section class="v2-play"><div class="v2-shift-head"><div><div class="v2-kicker">THE NIGHT POST · DELIVERY ${g.index+1} OF ${g.deliveries.length}</div><h1>${esc(d.name)}</h1></div><div class="play-meta"><span class="pill">${g.solo?'SOLO':g.players.length+'/4 PLAYERS'}</span><span class="pill">${esc(g.difficulty)} · ${timeText}</span><button class="v4-top-utility ${ui.sidePanel==='postbag'?'active':''}" data-act="panel-postbag">Postbag</button><button class="v4-top-utility ${ui.sidePanel==='events'?'active':''}" data-act="panel-events">Activity</button><button class="v4-top-utility ${ui.sidePanel==='chat'?'active':''}" data-act="panel-chat">Chat</button><button class="v2-small-btn" data-act="leave">Exit</button></div></div>
<div class="v2-play-layout"><main class="v2-core"><div class="v2-objective"><span class="v2-objective-icon">✳</span><div><span>${lead[0]}</span><strong>${lead[1]}</strong></div><button class="v2-hint" data-act="hint">Need a hint? <small>${3-w.hintTier} left</small></button></div><div class="v2-tabs" aria-label="Work at a postal station"><button class="${ui.deskMode==='letter'?'active':''}" data-act="view-letter">1 · The letter</button><button class="${ui.deskMode==='atlas'?'active':''}" data-act="view-atlas">2 · Folded world</button><button class="${ui.deskMode==='dispatch'?'active':''}" data-act="view-dispatch">3 · Dispatch</button></div>${ui.deskMode==='letter'?letterStage:ui.deskMode==='atlas'?worldStage:worldStage}<div class="v2-work-controls">${ui.deskMode==='letter'?`<div class="v2-letter-next"><span>The address identifies the destination. The folding atlas shows what prevents your courier from reaching it.</span><button class="primary" data-act="view-atlas">Unfold the destination →</button></div>`:''}</div></main>
${ui.sidePanel?`<aside class="v2-side v4-drawer"><div class="v2-side-toolbar"><button class="${ui.sidePanel==='postbag'?'active':''}" data-act="panel-postbag">Postbag <small>${g.completed.length}/${g.deliveries.length}</small></button><button class="${ui.sidePanel==='events'?'active':''}" data-act="panel-events">Activity</button><button class="${ui.sidePanel==='chat'?'active':''}" data-act="panel-chat">Chat ${g.chat.length?'· '+g.chat.length:''}</button></div>${sideHtml}<div class="v2-teamline">${g.players.length} worker${g.players.length!==1?'s':''} on duty · ${g.visibility==='public'?'Public':'Private'} shift</div></aside>`:''}</div></section>`)}
function finish(){let g=ui.game;return shell(`<section class="finish"><div class="eyebrow">POSTAL MINISTRY · SHIFT REPORT</div><div class="wax">✦</div><h1>${g.completed.length===2?'The impossible was delivered.':'The shift has ended.'}</h1><p>${g.completed.length===2?'Two pieces of undeliverable correspondence found their way home. The archive will insist this never happened.':'Some routes remain incomplete. The Bureau will return the mail to your desk.'}</p><div class="score-row"><div class="score-tile"><strong>${g.completed.length}/2</strong><small>Delivered</small></div><div class="score-tile"><strong>${g.score}</strong><small>Office points</small></div><div class="score-tile"><strong>${g.errors}</strong><small>Misroutes</small></div><div class="score-tile"><strong>${g.hintsUsed}</strong><small>Hints used</small></div></div><p class="tiny muted" style="margin-bottom:24px">The next shift varies its route directions, handling instructions, and timing conditions. Try again without hints, or bring colleagues.</p><div class="auth-row" style="justify-content:center"><button class="primary" data-act="solo">New solo shift</button><button class="secondary" data-act="coop">Play with friends</button><button class="subtle" data-act="home">Return to desk</button></div></section>`)}
function dialog(){let g=ui.game,d=g?E.current(g):null;if(!ui.modal)return'';let m=ui.modal;
 if(m==='how')return `<div class="backdrop" role="presentation"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="mdhead"><header><div><span class="eyebrow">OFFICIAL ORIENTATION</span><h2 id="mdhead">Read. Reconfigure. Deliver.</h2></div><button class="icon-btn" data-act="close" aria-label="Close">×</button></header><div class="modal-body"><div class="document"><h3>Four truths about the Ministry</h3><p><b>01 · Mail is evidence.</b> Read the address, flip the envelope, unfold the atlas, and consult the postal register. Every correct solution is deducible.</p><p><b>02 · Worlds are machinery.</b> Brace a fold and turn a destination. In online play, the person holding the fold cannot be the one who rotates. In solo play, a desk clamp holds it for you.</p><p><b>03 · Conditions still matter.</b> Set the clock or tide, choose a postage stamp, then dispatch through a complete route. A guess costs points.</p><p><b>04 · Share the work.</b> Talk in chat, watch your teammates change the world, and use the activity feed. Public and private rooms both support two to four real people.</p><p class="small">Two handcrafted deliveries are included in this first shift. Standard mode has a 15-minute clock; Expert has 8 minutes; Untimed retains all puzzles without a timer.</p></div><div class="modal-actions"><button class="primary" data-act="close">Return to the desk</button></div></div></section></div>`;
 let titles={front:'The address',reverse:'Reverse postmark',atlas:'The folding atlas',ledger:'The postal register'};let val={front:d?.front,reverse:d?.reverse,atlas:d?.atlas,ledger:d?.ledger};let selected=titles[m]?m:'front';return `<div class="backdrop" role="presentation"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="mdhead"><header><div><span class="eyebrow">ITEM ${esc(d?.number||'')} · EVIDENCE</span><h2 id="mdhead">${esc(titles[selected])}</h2></div><button class="icon-btn" data-act="close" aria-label="Close">×</button></header><div class="modal-body"><div class="document"><span class="stamp-icon">${selected==='ledger'?'▤':selected==='atlas'?'◈':'✉'}</span><span class="caps">UNDELIVERABLE CORRESPONDENCE · ARCHIVE COPY</span><h3 style="margin-top:10px">${selected==='front'?esc(d?.recipient):selected==='reverse'?'Notes from the transfer press':selected==='atlas'?'Cartographic division':'Postage classification'}</h3><p>${esc(val[selected])}</p><div class="line" style="background:#88705266;margin:17px 0"></div><p class="small">${selected==='front'?'The delivery instructions tell you the required conditions, not which buttons to press.':selected==='reverse'?'What looks east on one side of the folded world may be west on the other.':selected==='atlas'?'Bracing and rotating may require two pairs of hands when playing online.':'A correct physical route still requires valid postage.'}</p></div><div class="modal-actions">${Object.keys(titles).map(t=>`<button class="${t===selected?'primary':'subtle'}" data-act="inspect" data-target="${t}">${esc(titles[t])}</button>`).join('')}</div></div></section></div>`}
function render(){const oldFocused=document.activeElement?.id;const selection=document.activeElement?.selectionStart;const oldChat=document.getElementById('chatlist');const scrollBottom=oldChat?oldChat.scrollTop+oldChat.clientHeight>=oldChat.scrollHeight-20:true;
 root.innerHTML=ui.screen==='home'?home():ui.screen==='briefing'?briefing():ui.screen==='auth'?auth():ui.screen==='lobby'?lobby():ui.screen==='play'?play():ui.screen==='finished'?finish():home();
 if(oldFocused==='chatinput'){let target=document.getElementById('chatinput');if(target&&!target.disabled){target.focus();try{target.setSelectionRange(selection,selection)}catch{}}}let chat=document.getElementById('chatlist');if(chat&&scrollBottom)chat.scrollTop=chat.scrollHeight;
}
function assignState(g){const prev=ui.lastSeq;ui.game=g;if(prev!=null){let events=g.events.filter(e=>e.seq>prev);let most=events.at(-1);if(most&&['DELIVERED','INCOMING','MISHAP','ROTATE','FOLD','DISPATCH','SPILL','CLEAR'].includes(most.type)){const serial=Date.now();ui.notice={text:most.message,type:cat(most.type),serial};setTimeout(()=>{if(ui.notice?.serial===serial){ui.notice=null;render()}},4200)}}ui.lastSeq=g.version;if(g.phase==='finished')ui.screen='finished';else if(g.phase==='playing')ui.screen=(ui.online&&ui.introDismissedFor!==g.code)?'briefing':'play';else ui.screen='lobby';render();}
function closeStream(){if(ui.stream){ui.stream.close();ui.stream=null}}
async function api(path,payload){const res=await fetch(path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});let j=await res.json().catch(()=>({error:'Network response could not be read.'}));if(!res.ok)throw Error(j.error||`HTTP ${res.status}`);return j}
async function refreshPublic(){try{let r=await fetch('/api/public',{cache:'no-store'});if(r.ok)ui.publicRooms=(await r.json()).rooms||[];}catch{ui.publicRooms=[];}render()}
function connect(){closeStream();if(!ui.token||!ui.game?.code)return;let ev=new EventSource(`/api/events?code=${encodeURIComponent(ui.game.code)}&token=${encodeURIComponent(ui.token)}`);ui.stream=ev;ev.addEventListener('state',e=>{try{assignState(JSON.parse(e.data))}catch{}});ev.addEventListener('error',()=>{if(ui.game&&ui.game.phase!=='finished')console.warn('Office connection interrupted. Reconnecting…');});}
function leave(){closeStream();ui.pendingStart=null;ui.introDismissedFor=null;ui.deskMode='letter';ui.lastDeliveryIndex=null;ui.game=null;ui.token=null;ui.playerId=null;ui.lastSeq=null;ui.online=false;ui.screen='home';ui.modal=null;ui.draft='';try{sessionStorage.removeItem('postmarked-online')}catch{};render()}
function beginSolo(){closeStream();ui.online=false;ui.deskMode='letter';ui.lastDeliveryIndex=null;ui.playerId='solo';ui.token=null;ui.lastSeq=null;ui.game=E.createGame({solo:true,name:ui.name,difficulty:ui.difficulty,seed:Math.floor(1+Math.random()*999999)});ui.screen='play';ui.modal=null;render()}
async function sendAction(action){if(!ui.game)return;try{if(!ui.online){let r=E.apply(ui.game,ui.playerId,action);if(r.error){render();setNotice(r.error,'error');return;}if(r.dispatch)setTimeout(()=>{E.finalizeDelivery(ui.game);assignState(ui.game)},1850);assignState(ui.game);return;}let r=await api('/api/action',{code:ui.game.code,token:ui.token,action});assignState(r.state)}catch(e){setNotice(e.message,'error')}}
function copyText(text){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>setNotice('Copied to clipboard.','success')).catch(()=>setNotice('Copy this code: '+text));else setNotice('Copy: '+text)}
async function joinRoom(code){try{ui.busy=true;render();const j=await api('/api/join',{code,name:ui.name});ui.busy=false;ui.online=true;ui.token=j.token;ui.playerId=j.playerId;ui.lastSeq=null;try{sessionStorage.setItem('postmarked-online',JSON.stringify({code:j.code,token:j.token,playerId:j.playerId}))}catch{}assignState(j.state);connect();}catch(e){ui.busy=false;setNotice(e.message,'error')}}
async function createRoom(){try{ui.busy=true;render();const j=await api('/api/create',{visibility:ui.visibility,difficulty:ui.difficulty,name:ui.name});ui.busy=false;ui.online=true;ui.token=j.token;ui.playerId=j.playerId;ui.lastSeq=null;try{sessionStorage.setItem('postmarked-online',JSON.stringify({code:j.code,token:j.token,playerId:j.playerId}))}catch{}assignState(j.state);connect();}catch(e){ui.busy=false;setNotice(e.message,'error')}}
function handleAction(action,btn){switch(action){case'home':leave();break;case'how':ui.modal='how';render();break;case'close':ui.modal=null;render();break;case'solo':ui.pendingStart='solo';ui.screen='briefing';ui.modal=null;render();break;case'intro-enter':if(ui.pendingStart==='solo'){ui.pendingStart=null;beginSolo();}else{ui.introDismissedFor=ui.game?.code||null;ui.screen='play';render();}break;case'coop':if(location.protocol==='file:'){setNotice('Online multiplayer needs a hosted game server. Use the public playtest URL or run npm start.','error');break;}ui.screen='auth';ui.modal=null;render();refreshPublic();break;case'set-vis':ui.visibility=btn.dataset.value;render();break;case'create':createRoom();break;case'join':joinRoom(ui.joinCode);break;case'join-public':joinRoom(btn.dataset.code);break;case'refresh-public':refreshPublic();break;case'ready':{let me=ui.game.players.find(p=>p.id===ui.playerId);sendAction({type:'READY',ready:!me.ready});break;}case'start':sendAction({type:'START'});break;case'lobby-vis':sendAction({type:'VISIBILITY',visibility:btn.dataset.value});break;case'copy-code':copyText(ui.game?.code||'');break;case'copy-link':copyText(`${location.origin}${location.pathname}?room=${encodeURIComponent(ui.game?.code||'')}`);break;case'inspect':{const target=btn.dataset.target;ui.modal=target;sendAction({type:'INSPECT',target});break;}case'view-letter':ui.deskMode='letter';render();break;case'view-atlas':ui.deskMode='atlas';sendAction({type:'INSPECT',target:'atlas'});break;case'view-dispatch':ui.deskMode='dispatch';render();break;case'open-front':ui.deskMode='letter';ui.letterSide='front';sendAction({type:'INSPECT',target:'front'});break;case'open-back':ui.deskMode='letter';ui.letterSide='reverse';sendAction({type:'INSPECT',target:'reverse'});break;case'open-ledger':ui.deskMode='letter';ui.letterSide='ledger';sendAction({type:'INSPECT',target:'ledger'});break;case'panel-chat':ui.sidePanel=ui.sidePanel==='chat'?null:'chat';render();break;case'panel-events':ui.sidePanel=ui.sidePanel==='events'?null:'events';render();break;case'panel-postbag':ui.sidePanel=ui.sidePanel==='postbag'?null:'postbag';render();break;case'fold':sendAction({type:'FOLD'});break;case'blot':sendAction({type:'BLOT',spot:Number(btn.dataset.spot)});break;case'rotate':sendAction({type:'ROTATE',dir:Number(btn.dataset.dir)});break;case'dial':sendAction({type:'DIAL',value:btn.dataset.value});break;case'stamp':sendAction({type:'STAMP',value:btn.dataset.value});break;case'hint':sendAction({type:'HINT'});break;case'dispatch':sendAction({type:'DISPATCH'});break;case'leave':leave();break;default:break;}}
root.addEventListener('click',e=>{let btn=e.target.closest('[data-act]');if(!btn||btn.disabled)return;e.preventDefault();handleAction(btn.dataset.act,btn)});root.addEventListener('keydown',e=>{if(!['Enter',' '].includes(e.key))return;let t=e.target.closest?.('g.world-hotspot[data-act]');if(t){e.preventDefault();handleAction(t.dataset.act,t)}});
root.addEventListener('change',e=>{let key=e.target?.dataset?.field;if(!key)return;ui[key]=String(e.target.value);if(key==='name'){ui.name=E.safeName(ui.name);try{localStorage.setItem('postmarked-name',ui.name)}catch{}}render()});
root.addEventListener('input',e=>{if(e.target.id==='chatinput')ui.draft=e.target.value;const key=e.target?.dataset?.field;if(key)ui[key]=String(e.target.value).slice(0,100)});
root.addEventListener('submit',async e=>{if(e.target.dataset.form!=='chat')return;e.preventDefault();let txt=ui.draft.trim();if(!txt||!ui.online)return;ui.draft='';render();try{await api('/api/chat',{code:ui.game.code,token:ui.token,text:txt})}catch(e){ui.draft=txt;setNotice(e.message,'error')}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.modal){ui.modal=null;render()}});
if(ui.joinCode){ui.screen='auth';setTimeout(refreshPublic,100)}render();
setInterval(()=>{if(ui.screen==='play'&&ui.game?.startedAt&&E.limitSeconds(ui.game)){let elem=root.querySelector('.play-meta .pill:nth-child(2)');if(elem){let max=E.limitSeconds(ui.game),remain=Math.max(0,max-Math.floor((Date.now()-ui.game.startedAt)/1000));elem.textContent=`${ui.game.difficulty} · ${String(Math.floor(remain/60)).padStart(2,'0')}:${String(remain%60).padStart(2,'0')}`;}if(!ui.online&&E.expired(ui.game)){ui.game.phase='finished';ui.screen='finished';render();}}},1000);
})();
